const targets = msg.payload.targets || [];
let processedTargets = [];

// Neuer Skalierungsfaktor für das SVG (Breite max 100, Höhe max 125)
// 125 Pixel entsprechen 6000 mm (6 Metern) -> Faktor: 0.020833
const scale = 125 / 6000;

// Berechnung für maximal 3 Targets (IDs 0, 1, 2)
for (let i = 0; i < 3; i++) {
    let target = targets.find(t => t.id === i);
    if (target) {

        // X-Berechnung: Startet in der Mitte (50) und skaliert den Millimeter-Wert
        let xPixel = 50 + (target.x * scale);

        // Y-Berechnung: Startet unten beim Sensor (125) und wandert nach oben (Minus)
        let yPixel = 125 - (target.y * scale);

        processedTargets.push({
            id: target.id,
            x: Math.round(xPixel * 100) / 100, // Auf 2 Dezimalstellen runden
            y: Math.round(yPixel * 100) / 100,
            s: target.s,
            visible: true
        });
    } else {
        // Falls Target nicht aktiv, als unsichtbar markieren
        processedTargets.push({ id: i, visible: false });
    }
}

// Daten für das neue Dashboard-Template verpacken
msg.payload = {
    targets: processedTargets,
    // Den Status aus dem Speicher holen (Standardwert ist "OFF")
    alertStatus: global.get("radar_target_alert") || "OFF"
};

return msg;

// Den Zustand (ON oder OFF) in den globalen Speicher schreiben
// Wir wandeln den Text zur Sicherheit in Kleinbuchstaben um, falls "On" oder "on" gesendet wird.
const status = (msg.payload || "").toString().toLowerCase();

if (status.includes("on")) {
    global.set("radar_target_alert", "ON");
} else {
    global.set("radar_target_alert", "OFF");
}

return msg; // Es muss hier nichts direkt weitergeleitet werden

const targets = msg.payload.targets || [];
let processedTargets = [];

const svgWidth = 100; // ca. 33% mehr Dehnung,  statt 100;
const svgHeight = 125;
const scale = svgHeight / 6000;

const targetMap = {};
for (let t of targets) {
    targetMap[t.id] = t;
}

// Hilfsvariable für den geringsten Y-Abstand in mm (Start bei unendlich)
let minMillimeterY = Infinity; 

for (let i = 0; i < 3; i++) {
    let target = targetMap[i];

    if (target) {
        let xPixel = 50 + (target.x * scale * 1.6); // x-Dehnfaktor
        let yPixel = svgHeight - (target.y * scale);

        let xPercent = (xPixel / svgWidth) * 100;
        let yPercent = (yPixel / svgHeight) * 100;

        // Finde das Target mit dem geringsten Abstand (target.y ist der echte mm-Wert)
        if (target.y < minMillimeterY) {
            minMillimeterY = target.y;
        }

        processedTargets.push({
            id: i,
            x: Number(xPixel.toFixed(2)),
            y: Number(yPixel.toFixed(2)),
            px: Number(xPercent.toFixed(2)),
            py: Number(yPercent.toFixed(2)),
            s: target.s ?? 0,
            visible: true
        });
    } else {
        processedTargets.push({
            id: i,
            visible: false
        });
    }
}

// Zonen-Logik basierend auf den echten Millimeter-Werten
let distZone = "NONE";
let minDist = 0;
// last segment nach "/"
const parts = (msg.topic || "").split('/');
msg.sensorid = parts[parts.length - 1];
if (minMillimeterY !== Infinity) {
    minDist = minMillimeterY; // Gibt den minimalen Abstand in mm aus

    if (minDist <= 2000) {
        distZone = "NEAR";       // 0m bis 2m
    } else if (minDist <= 4000) {
        distZone = "MEDIUM";     // >2m bis 4m
    } else {
        distZone = "FAR";        // >4m bis 6m
    }
}

msg.payload = {
    targets: processedTargets,
    alertStatus: global.get("radar_target_alert") || "OFF",
    minDist: minDist, // minimaler Abstand in mm
    distZone: distZone, // "NEAR", "MEDIUM", "FAR" oder "NONE"
    sensorid: msg.sensorid
};

return msg;

// Ausschaltverzögerung in Millisekunden (5 Sekunden)
const OFF_DELAY = 5000;

// 1. Speicher aus dem Kontext holen
let sensorRegister = context.get('sensorRegister') || {};
let currentStatus = context.get('currentStatus') || 'OFF';
let offTimer = context.get('offTimer') || null;

// 2. Eingehende Daten direkt aus msg.payload lesen
let incoming = msg.payload;
if (typeof incoming === "string") {
    try { incoming = JSON.parse(incoming); } catch(e) { incoming = {}; }
}

// 3. Sensor-ID und Konfigurationsdaten direkt aus der Payload extrahieren
let id = incoming.sensorid;

if (id) {
    // Falls Daten fehlen, Fallbacks nutzen
    const config = {
        sensorBez: incoming.sensorBez || "Unbekannter Sensor",
        offsetX: typeof incoming.offsetX === "number" ? incoming.offsetX : 0,
        offsetY: typeof incoming.offsetY === "number" ? incoming.offsetY : 0,
        winkel: typeof incoming.winkel === "number" ? incoming.winkel : 0
    };

    // Original-Targets holen (Struktur: incoming.targets)
    let rawTargets = incoming.targets || [];
    let transformedTargets = [];

    // MATHEMATISCHE BERECHNUNG DER TARGET-POSITIONEN
    rawTargets.forEach(t => {
        // Winkel in Bogenmass umrechnen
        let alpha = config.winkel * Math.PI / 180;

        // Bezugspunkt-Korrektur (Übernommen aus Originalcode)
        let relX = t.x - 50;
        let relY = 125 - t.y; 

        // Rotationsmatrix anwenden
        let rotX = relX * Math.cos(alpha) + relY * Math.sin(alpha);
        let rotY = relX * Math.sin(alpha) - relY * Math.cos(alpha);

        // Globale Position auf dem Hausplan berechnen
        let finalX = config.offsetX + rotX;
        let finalY = config.offsetY - rotY;

        // Objekt befüllen (Feld "visible" entfernt, da im Input nicht vorhanden)
        transformedTargets.push({
            id: t.id,
            x: Math.round(finalX),
            y: Math.round(finalY),
            s: t.s // Grösse/Status mitsichern
        });
    });

    // Sensor im Register aktualisieren
    sensorRegister[id] = {
        sensorid: id,
        sensorBez: config.sensorBez,
        offsetX: config.offsetX,
        offsetY: config.offsetY,
        winkel: config.winkel,
        targets: transformedTargets
    };
}

context.set('sensorRegister', sensorRegister);

// 4. Prüfen, ob aktuell IRGENDEIN Sensor ein echtes Target sieht
const sensorArray = Object.values(sensorRegister);
const rawTargetDetected = sensorArray.some(sensor => 
    sensor.targets && sensor.targets.length > 0
);

// 5. Verzögerungs-Logik (Debounce)
if (rawTargetDetected) {
    if (offTimer) {
        clearTimeout(offTimer);
        context.set('offTimer', null);
    }
    currentStatus = 'ON';
    context.set('currentStatus', currentStatus);

    msg.payload = { sensors: sensorArray, globalAlertStatus: currentStatus };
    node.send(msg);
} else {
    if (currentStatus === 'ON') {
        if (!offTimer) {
            offTimer = setTimeout(() => {
                let freshRegister = context.get('sensorRegister') || {};
                context.set('currentStatus', 'OFF');
                context.set('offTimer', null);

                node.send({
                    payload: {
                        sensors: Object.values(freshRegister),
                        globalAlertStatus: 'OFF'
                    }
                });
            }, OFF_DELAY);

            context.set('offTimer', offTimer);
        }
    }

    msg.payload = { sensors: sensorArray, globalAlertStatus: currentStatus };
    node.send(msg);
}

return null;

// 1. FEHLERSCHUTZ: Falls die Payload noch Text ist, in JSON umwandeln
if (typeof msg.payload === "string") {
    try {
        msg.payload = JSON.parse(msg.payload);
    } catch(e) {
        node.error("Payload ist kein gültiges JSON: " + msg.payload);
        return msg;
    }
}

// 2. Sensor-ID aus dem Topic holen
// Falls msg.topic leer oder kein String ist, nutzen wir einen Fallback ("unbekannt")
let sensorId = "unbekannt";
if (msg.topic && typeof msg.topic === "string") {
    let topicParts = msg.topic.split('/');
    // Filtert leere Einträge (falls das Topic mit / endet)
    topicParts = topicParts.filter(part => part.length > 0); 
    if (topicParts.length > 0) {
        sensorId = topicParts[topicParts.length - 1];
    }
}

// 3. Sensor-ID in das Array einfügen
if (Array.isArray(msg.payload)) {
    msg.payload = msg.payload.map(item => {
        if (typeof item === 'object' && item !== null) {
            item.sensorid = sensorId; // Fügt das Feld direkt hinzu
        }
        return item;
    });
} else if (typeof msg.payload === 'object' && msg.payload !== null) {
    // Falls es doch kein Array, sondern ein einzelnes Objekt ist
    msg.payload.sensorid = sensorId;
}

return msg;

// 1. Die sensorid aus der aktuellen Payload auslesen
let sensorId = msg.payload.sensorid;

// 2. Den globalen Context "sensorConfig" abrufen
let sensorConfig = global.get("sensorConfig") || {};

// 3. Die passenden Sensordaten aus der Tabelle holen
let config = sensorConfig[sensorId];

// 4. Wenn der Sensor in der Tabelle existiert, die Felder ergänzen
if (config) {
    msg.payload.offsetX = config.offsetX;
    msg.payload.offsetY = config.offsetY;
    msg.payload.winkel = config.winkel;
    msg.payload.sensorBez = config.sensorBez;
}
msg.payload.occupancy =  msg.payload.targets.length > 0 ? 1 : 0 ;
return msg;

// ==================== KALIBRIERUNG ====================
// MASSSTAB: Wie viele Pixel auf der Zeichnung entsprechen einer Sensor-Einheit?
// Wenn der Sensor in cm misst und deine Zeichnung 800px breit ist, versuche z.B. 0.5 oder 0.2
const SCALE = 0.05; 

// SENSOR-URSPRUNG: Werkseitiger Mittelpunkt der Hardware (LD2410 Standard: X=50, Y=125)
const HARDWARE_CENTER_X = 50;
const HARDWARE_CENTER_Y = 125;
// ======================================================

let incoming = msg.payload;
if (typeof incoming === "string") {
    try { incoming = JSON.parse(incoming); } catch(e) { return msg; }
}

let offsetX = typeof incoming.offsetX === "number" ? incoming.offsetX : 0;
let offsetY = typeof incoming.offsetY === "number" ? incoming.offsetY : 0;
let winkel = typeof incoming.winkel === "number" ? incoming.winkel : 0;

if (incoming.targets && Array.isArray(incoming.targets)) {
    incoming.targets = incoming.targets.map(t => {
        let alpha = winkel * Math.PI / 180;

        // 1. Relativen Abstand zum Hardware-Nullpunkt berechnen
        let relX = t.x - HARDWARE_CENTER_X;
        let relY = HARDWARE_CENTER_Y - t.y; 

        // 2. Den Massstab auf die relative Distanz anwenden (Skalierung)
        relX = relX * SCALE;
        relY = relY * SCALE;

        // 3. Rotationsmatrix anwenden (Winkel-Drehung)
      //  let rotX = relX * Math.cos(alpha) + relY * Math.sin(alpha);
      //  let rotY = -relX * Math.sin(alpha) +  relY * Math.cos(alpha);

        // 3. Rotationsmatrix anwenden (Winkel-Drehung für dein System)
      //  let rotX = relX * Math.cos(alpha) - relY * Math.sin(alpha);
      //  let rotY = relX * Math.sin(alpha) + relY * Math.cos(alpha);

        // 3. Rotationsmatrix anwenden (Perfekt abgestimmt auf dein System)
        let rotX = relX * Math.cos(alpha) - relY * Math.sin(alpha);
        let rotY = -relX * Math.sin(alpha) - relY * Math.cos(alpha);

        // 4. Globale Position auf dem Hausplan (SVG-Pixel) berechnen
        let finalX = offsetX + rotX;
        let finalY = offsetY - rotY;

        return {
            id: t.id,
            s: t.s,
            x: Math.round(finalX),
            y: Math.round(finalY)
        };
    });
}

msg.payload = incoming;
return msg;

// Bestehendes Sensor-Objekt aus dem Kontext holen oder neu erstellen
let sensors = context.get('radar_sensors') || {};

// Prüfen, ob die MQTT-Nachricht gültige Radardaten enthält
if (msg.payload && msg.payload.sensorid) {
    // Speichere oder aktualisiere die Daten dieses spezifischen Sensors
    sensors[msg.payload.sensorid] = msg.payload;

    // Im Kontext für die nächste Nachricht sichern
    context.set('radar_sensors', sensors);
}

// Wir wandeln das Objekt in ein Array (Liste) um, 
// damit Vue im Dashboard einfach per v-for darüber loopen kann.
msg.payload = Object.values(sensors);

return msg;

// Prüfen, ob die Payload ein Array ist
if (Array.isArray(msg.payload)) {

    // Das neue Zielobjekt initialisieren
    let neueStruktur = {};

    // Jedes Element aus dem Input-Array durchlaufen
    msg.payload.forEach(item => {

        // Den Sensor-Schlüssel dynamisch bestimmen (z.B. "RD06D_05" -> "rd06d_05")
        // Falls der Schlüssel exakt so bleiben soll wie im Input, das .toLowerCase() einfach löschen
        let sensorKey = item.sensorid ? item.sensorid.toLowerCase() : "unbekannt";

        // Die exakte neue Feldstruktur mit korrekter Gross-/Kleinschreibung aufbauen
        neueStruktur[sensorKey] = {
            "offsetX": item.offsetx,
            "offsetY": item.offsety,
            "winkel": item.winkel,
            "sensorBez": item.sensorbez
        };
    });
    // 1. Die Struktur in der globalen Variable "sensorConfig" speichern
    global.set("sensorConfig", neueStruktur);
    // Die transformierte Struktur an die Payload übergeben
    msg.payload = neueStruktur;
}

return msg;
